"""### 8. Prepare data loaders
Now we are ready to instantiate our data loaders. For this we will need to import PyTorch Geometric, our GNN library.
"""

from relbench.modeling.graph import get_node_train_table_input, make_pkey_fkey_graph
from torch_geometric.loader import NeighborLoader

loader_dict = {}

for split, table in [
    ("train", train_table),
    ("val", val_table),
    ("test", test_table),
]:
    table_input = get_node_train_table_input(
        table=table,
        task=task,
    )
    entity_table = table_input.nodes[0]
    loader_dict[split] = NeighborLoader(
        data,
        num_neighbors=[
            128 for i in range(2)
        ],  # we sample subgraphs of depth 2, 128 neighbors per node.
        time_attr="time",
        input_nodes=table_input.nodes,
        input_time=table_input.time,
        transform=table_input.transform,
        batch_size=512,
        temporal_strategy="uniform",
        shuffle=split == "train",
        num_workers=0,
        persistent_workers=False,
    )

"""# Part III: Building a GNN for RDL
Now we build a GNN model that can be trained to predict the labels for a given task in RelBench.

### Define HeteroTemporal Encoder

Computes relative time of a node
"""

from torch_geometric.typing import EdgeType, NodeType
from torch_geometric.nn import PositionalEncoding
from typing import Any, Dict, List, Optional


# adapted from https://github.com/tgm-team/tgm/blob/main/tgm/core/timedelta.py
_UNIT_TO_NANOS = {
        'Y': 1000 * 1000 * 1000 * 60 * 60 * 24 * 365,
        'M': 1000 * 1000 * 1000 * 60 * 60 * 24 * 30,
        'W': 1000 * 1000 * 1000 * 60 * 60 * 24 * 7,
        'D': 1000 * 1000 * 1000 * 60 * 60 * 24,
        'h': 1000 * 1000 * 1000 * 60 * 60,
        'm': 1000 * 1000 * 1000 * 60,
        's': 1000 * 1000 * 1000,
        }

class HeteroTemporalEncoder(torch.nn.Module):
    def __init__(self, node_types: List[NodeType], channels: int, time_gran: str = 'D'):
        super().__init__()

        self.encoder_dict = torch.nn.ModuleDict(
            {node_type: PositionalEncoding(channels) for node_type in node_types}
        )
        self.lin_dict = torch.nn.ModuleDict(
            {node_type: torch.nn.Linear(channels, channels) for node_type in node_types}
        )
        self.default = "s"
        if (time_gran not in _UNIT_TO_NANOS):
          raise ValueError("time granularity not supported")
        self.unit = self._convert('s',time_gran)


    def _convert(self, time_1: str, time_2: str) -> float:
        self_nanos = _UNIT_TO_NANOS[time_1]
        other_nanos = _UNIT_TO_NANOS[time_2]

        if self_nanos > other_nanos:
          unit_ratio = self_nanos // other_nanos
        else:
          unit_ratio = other_nanos // self_nanos
        return unit_ratio

    def reset_parameters(self):
        for encoder in self.encoder_dict.values():
            encoder.reset_parameters()
        for lin in self.lin_dict.values():
            lin.reset_parameters()

    def forward(
        self,
        seed_time: Tensor,
        time_dict: Dict[NodeType, Tensor],
        batch_dict: Dict[NodeType, Tensor],
    ) -> Dict[NodeType, Tensor]:
        out_dict: Dict[NodeType, Tensor] = {}

        for node_type, time in time_dict.items():
            rel_time = seed_time[batch_dict[node_type]] - time
            rel_time = rel_time / self.unit # convert seconds to a coarse graine time granularity

            x = self.encoder_dict[node_type](rel_time)
            x = self.lin_dict[node_type](x)
            out_dict[node_type] = x

        return out_dict

"""### 9. Define GNN Model"""

from typing import Any, Dict, List
import numpy as np

from torch.nn import BCEWithLogitsLoss
from torch import Tensor
from torch.nn import Embedding, ModuleDict
from torch_frame.data.stats import StatType
from torch_geometric.data import HeteroData
from torch_geometric.nn import MLP
from torch_geometric.typing import NodeType

from relbench.modeling.nn import HeteroEncoder, HeteroGraphSAGE

class Model(torch.nn.Module):

    def __init__(
        self,
        data: HeteroData,
        col_stats_dict: Dict[str, Dict[str, Dict[StatType, Any]]],
        num_layers: int,
        channels: int,
        out_channels: int,
        aggr: str,
        norm: str,
        # List of node types to add shallow embeddings to input
        shallow_list: List[NodeType] = [],
    ):
        super().__init__()

        self.encoder = HeteroEncoder(
            channels=channels,
            node_to_col_names_dict={
                node_type: data[node_type].tf.col_names_dict
                for node_type in data.node_types
            },
            node_to_col_stats=col_stats_dict,
        )
        self.temporal_encoder = HeteroTemporalEncoder(
            node_types=[
                node_type for node_type in data.node_types if "time" in data[node_type]
            ],
            channels=channels,
            time_gran='D', #'W','M'
        )
        self.gnn = HeteroGraphSAGE(
            node_types=data.node_types,
            edge_types=data.edge_types,
            channels=channels,
            aggr=aggr,
            num_layers=num_layers,
        )
        self.head = MLP(
            channels,
            out_channels=out_channels,
            norm=norm,
            num_layers=1,
        )
        self.embedding_dict = ModuleDict(
            {
                node: Embedding(data.num_nodes_dict[node], channels)
                for node in shallow_list
            }
        )

        self.id_awareness_emb = None
        self.reset_parameters()

    def reset_parameters(self):
        self.encoder.reset_parameters()
        self.temporal_encoder.reset_parameters()
        self.gnn.reset_parameters()
        self.head.reset_parameters()
        for embedding in self.embedding_dict.values():
            torch.nn.init.normal_(embedding.weight, std=0.1)

    def forward(
        self,
        batch: HeteroData,
        entity_table: NodeType,
    ) -> Tensor:
        seed_time = batch[entity_table].seed_time
        x_dict = self.encoder(batch.tf_dict)

        rel_time_dict = self.temporal_encoder(
            seed_time, batch.time_dict, batch.batch_dict
        )

        for node_type, rel_time in rel_time_dict.items():
            x_dict[node_type] = x_dict[node_type] + rel_time

        for node_type, embedding in self.embedding_dict.items():
            x_dict[node_type] = x_dict[node_type] + embedding(batch[node_type].n_id)

        x_dict = self.gnn(
            x_dict,
            batch.edge_index_dict,
            batch.num_sampled_nodes_dict,
            batch.num_sampled_edges_dict,
        )

        return self.head(x_dict[entity_table][: seed_time.size(0)])


model = Model(
    data=data,
    col_stats_dict=col_stats_dict,
    num_layers=2,
    channels=128,
    out_channels=1,
    aggr="sum",
    norm="batch_norm",
).to(device)


optimizer = torch.optim.Adam(model.parameters(), lr=0.005)
epochs = 10

print(model)

"""### 10. Train and test functions"""

tune_metric = "roc_auc"
loss_fn = BCEWithLogitsLoss()
higher_is_better = True # for classification task
# higher_is_better = False # for regression task

def train() -> float:
    model.train()

    loss_accum = count_accum = 0
    for batch in tqdm(loader_dict["train"]):
        batch = batch.to(device)

        optimizer.zero_grad()
        pred = model(
            batch,
            task.entity_table,
        )
        pred = pred.view(-1) if pred.size(1) == 1 else pred

        loss = loss_fn(pred.float(), batch[entity_table].y.float())
        loss.backward()
        optimizer.step()

        loss_accum += loss.detach().item() * pred.size(0)
        count_accum += pred.size(0)

    return loss_accum / count_accum


@torch.no_grad()
def test(loader: NeighborLoader) -> np.ndarray:
    model.eval()

    pred_list = []
    for batch in loader:
        batch = batch.to(device)
        pred = model(
            batch,
            task.entity_table,
        )
        pred = pred.view(-1) if pred.size(1) == 1 else pred
        pred_list.append(pred.detach().cpu())
    return torch.cat(pred_list, dim=0).numpy()

"""### 11. Training and evaluation"""

import math, copy
from tqdm import tqdm

state_dict = None
best_val_metric = -math.inf if higher_is_better else math.inf
for epoch in range(1, epochs + 1):
    train_loss = train()
    val_pred = test(loader_dict["val"])
    val_metrics = task.evaluate(val_pred, val_table)
    print(f"Epoch: {epoch:02d}, Train loss: {train_loss}, Val metrics: {val_metrics}")

    if (higher_is_better and val_metrics[tune_metric] > best_val_metric) or (
        not higher_is_better and val_metrics[tune_metric] < best_val_metric
    ):
        best_val_metric = val_metrics[tune_metric]
        state_dict = copy.deepcopy(model.state_dict())


model.load_state_dict(state_dict)
val_pred = test(loader_dict["val"])
val_metrics = task.evaluate(val_pred, val_table)
print(f"Best Val metrics: {val_metrics}")

test_pred = test(loader_dict["test"])
test_metrics = task.evaluate(test_pred)
print(f"Best test metrics: {test_metrics}")

"""### 12. Visualizing Sample Predictions"""

val_ground_truth = val_table.df['qualifying'].values

# Convert logits to probabilities using sigmoid
val_probabilities = torch.sigmoid(torch.tensor(val_pred)).numpy()

from sklearn.metrics import classification_report, confusion_matrix

val_predictions_binary = (val_probabilities >= 0.5).astype(int)

print("Classification Report:")
print(classification_report(val_ground_truth, val_predictions_binary,
                            target_names=['Top3', 'No']))

print("\nConfusion Matrix:")
print(confusion_matrix(val_ground_truth, val_predictions_binary))

import pandas as pd
import matplotlib.pyplot as plt

# Randomly sample 50 indices from the validation set
num_samples = 50
if len(val_ground_truth) < num_samples:
    num_samples = len(val_ground_truth)

sampled_indices = np.random.choice(len(val_ground_truth), num_samples, replace=False)

sampled_ground_truth = val_ground_truth[sampled_indices]
sampled_predictions = val_probabilities[sampled_indices]

# Create a DataFrame for easier plotting
plot_df = pd.DataFrame({
    'Sample Index': range(num_samples),
    'Ground Truth': sampled_ground_truth,
    'Predicted Probability': sampled_predictions
})

# Sort by predicted probability for better visualization
plot_df = plot_df.sort_values(by='Predicted Probability', ascending=False).reset_index(drop=True)

# # Plotting
# fig, ax = plt.subplots(figsize=(15, 7))

sampled_predictions_binary = (sampled_predictions >= 0.5).astype(int)
plot_df['Predicted Class'] = sampled_predictions_binary
plot_df['Correct'] = (plot_df['Predicted Class'] == plot_df['Ground Truth']).astype(int)

# color code by correctness
colors = ['green' if correct else 'red' for correct in plot_df['Correct']]

fig, ax = plt.subplots(figsize=(15, 7))
ax.scatter(range(num_samples), plot_df['Predicted Probability'],
           c=colors, s=100, alpha=0.6, edgecolors='black')
ax.axhline(y=0.5, color='blue', linestyle='--', label='Threshold (0.5)')
ax.scatter(range(num_samples), plot_df['Ground Truth'],
           marker='x', s=100, c='black', label='Ground Truth')

ax.set_xlabel('Sample Index')
ax.set_ylabel('Value')
ax.set_title(f'Predictions: Green=Correct, Red=Incorrect')
ax.legend()
plt.tight_layout()
plt.show()

print(f"Correct: {plot_df['Correct'].sum()}/{num_samples}")

task

